(()=>{'use strict';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const params=new URLSearchParams(location.search);let courseId=params.get('course')||'python-dsa',roomId=params.get('room')||'',courses=[],state=null,self=null,dirty=new Set(),revision=0,polling=false,sharedDrafts=[];const communityURL=(c=courseId,r='')=>'/community?course='+encodeURIComponent(c)+(r?'&room='+encodeURIComponent(r):'');const btn=(text,action,id='',extra='')=>`<button class="button outline" data-action="${action}" data-id="${esc(id)}" ${extra}>${text}</button>`;function notify(text){const el=$('community-feedback');if(el){el.hidden=false;el.textContent=text;}}async function api(body,poll=false){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),12000);try{const r=await fetch('/api/community?course='+encodeURIComponent(courseId)+(roomId?'&room='+encodeURIComponent(roomId)+'&panes=1':'')+(poll?'&poll=1':''),{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:ctrl.signal,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify({self,courseId,...body}):undefined});const v=await r.json();if(!r.ok)throw Object.assign(Error(v.error||'Community request failed'),{status:r.status});if(v.self){if(self&&v.self!==self)throw Object.assign(Error('Your signed-in account changed. Reload before continuing.'),{status:401});self=v.self;}return v;}finally{clearTimeout(timer);}}
const courseName=()=>courses.find(c=>c.id===courseId)?.title||'Course community';function base(){return `<p class="eyebrow">CODETRAIL / STUDY TOGETHER</p><h1 class="page-title">BETTER, TOGETHER.</h1><p class="page-subtitle">Find a study partner, share an approved coding room and discuss the course.</p><label class="field">Course community<select class="community-course" id="community-course">${courses.map(c=>`<option value="${c.id}" ${c.id===courseId?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><div class="community-discovery-link"><p>Find learners by name or by the city they choose to share.</p><a class="button outline" href="/people">Find learners ↗</a></div><div class="community-feedback" id="community-feedback" role="status" hidden></div>`;}
function joinForm(){return `<section class="panel social-form"><h2>Join ${esc(courseName())}</h2><p>Your display name appears beside comments and in rooms you share. Your email, profile preferences, course progress and private drafts are never listed here.</p><form id="join-form"><label class="field">Community display name<input id="community-handle" value="${esc(state.me?.handle||'')}" minlength="2" maxlength="40" placeholder="Choose a name other learners can recognize" required></label><label class="inline-check"><input type="checkbox" id="discoverable"><span>List my display name in this course's learner directory so others can request a study connection</span></label><p class="safe-note">Joining lets you read and post in this course discussion. Directory listing is optional. You choose what code to share, and only invited partners can view your coding rooms. Never post secrets or private personal information.</p><button class="button">Join course community ↗</button></form></section>`;}
function people(){return `<div class="notice">Only learners who opted into this course's directory are listed. A connection request shares your community display name. It does not expose either learner's private code.</div><div class="people-grid">${state.members.map(m=>{const c=state.connections.find(c=>c.learner.id===m.id);return `<article class="person"><div class="avatar small">${m.photoUrl?'<img class="learner-avatar-image" src="'+esc(m.photoUrl)+'" alt="Profile photo" loading="lazy">':esc(m.handle.slice(0,2).toUpperCase())}</div><h3>${esc(m.handle)}</h3><p>Enrolled in ${esc(courseName())}</p>${c?'<span class="tag">'+esc(c.status)+'</span>':btn('Connect ↗','connect',m.id)}${btn('Block','block',m.id)}</article>`;}).join('')||'<div class="empty">No other discoverable learners yet. Share the course link with a friend and invite them to join.</div>'}</div>`;}
function connections(){return `<section class="panel"><h2>Your study connections</h2><p>Accepting connects you in this course. Room access is granted separately by the room owner.</p>${state.connections.map(c=>`<div class="connection-row"><div><h3>${esc(c.learner.handle)}</h3><p>${c.status==='accepted'?'Connected · invite them into one of your rooms':c.incoming?'Wants to learn with you':'Request sent'}</p></div><div class="social-actions">${c.status==='pending'&&c.incoming?btn('Accept','accept',c.id)+btn('Decline','decline',c.id):''}${btn('Block','block',c.learner.id)}</div></div>`).join('')||'<p>No connections yet. Find a partner in the Learners tab.</p>'}</section>`;}
function messagesHTML(messages){return messages.map(m=>`<article class="chat-message ${m.mine?'mine':''}"><header><strong>${esc(m.author.handle)}${m.mine?' · you':''}</strong><time>${esc(new Date(m.createdAt).toLocaleString())}</time></header><p>${esc(m.body)}</p><div class="chat-actions">${m.mine?`<button data-action="${m.deleted?'restoreMessage':'deleteMessage'}" data-id="${m.id}">${m.deleted?'Restore comment':'Remove comment'}</button>`:`<button data-action="report" data-id="${m.id}">Report / hide</button><button data-action="block" data-id="${m.author.id}">Block author</button>`}</div></article>`).join('')||'<p class="muted">Start the conversation with a question, an insight or a helpful explanation.</p>';}
function chat(room=false){return `<section class="panel"><h2>${room?'Room discussion':'Course discussion'}</h2><p class="safe-note">${room?'Only the room owner and invited members can see these comments.':'Comments are visible to every learner who joins this course community. Be constructive; don’t post personal data or credentials.'}</p><div class="chat-feed" id="chat-feed" role="log" aria-live="polite">${messagesHTML(state.messages)}</div><form class="chat-compose" id="chat-form"><label class="field">Your comment<textarea id="comment-body" maxlength="3000" required placeholder="Ask a question or share a useful explanation…"></textarea></label><div class="button-row"><button class="button" id="post-comment" ${state.room?.closed?'disabled':''}>Post comment ↗</button><span class="poll-status" id="poll-status">Updates periodically while this page is visible</span></div></form></section>`;}
function rooms(){return `<div class="notice">A shared room starts private to you. Invite an accepted study partner to view it, then explicitly grant editor access if you want them to make corrections. Each learner sees their own editor first. Click a name to open that learner’s shared editor beside yours. Saved edits sync every few seconds; private practice drafts are never broadcast.</div>${state.rooms.map(r=>`<a class="room-card" href="${communityURL(courseId,r.id)}"><h3>${esc(r.title)} ↗</h3><p>${r.owned?'Your room':'Invited room'} · ${esc(r.language.toUpperCase())} · ${r.closed?'Closed':'Active'} · Updated ${esc(new Date(r.updatedAt).toLocaleString())}</p></a>`).join('')||'<p class="muted">No shared rooms yet. Create one below or ask a connected partner to invite you.</p>'}<section class="panel social-form" style="margin-top:25px"><h2>Create a coding room</h2><form id="room-form"><label class="field">Room title<input id="room-title" minlength="3" maxlength="80" placeholder="Working through binary search" required></label><label class="field">Language<select id="room-language"><option value="python">Python</option><option value="java">Java</option></select></label><button type="button" class="button outline" id="load-drafts">Choose from my saved drafts</button><select id="saved-drafts" aria-label="Saved draft to copy" hidden></select><label class="field" style="margin-top:20px">Code to share<textarea id="room-code" class="share-editor" maxlength="16000" spellcheck="false" placeholder="Paste only the code you want to share. Remove secrets first."></textarea></label><p class="safe-note">This creates a separate copy. Changes in this room do not overwrite your private course draft. Review the code before inviting anyone.</p><button class="button">Create private room ↗</button></form></section>`;}
function settings(){return `<section class="panel social-form"><h2>Your community presence</h2><form id="join-form"><label class="field">Community display name<input id="community-handle" value="${esc(state.me.handle)}" minlength="2" maxlength="40" required><small>This display name is used across your course communities.</small></label><label class="inline-check"><input id="discoverable" type="checkbox" ${state.discoverable?'checked':''}><span>Let enrolled learners find me in this course and request a study connection</span></label><button class="button">Save preferences</button></form><p class="safe-note">Leaving closes rooms you own in this course and removes your access to other rooms here. Your previous course comments remain; remove them first if you want. Private learning progress stays saved.</p>${btn('Leave community','leave')}<h2 style="margin-top:28px">Blocked learners</h2><p class="safe-note">Blocking hides each other's comments and removes access to each other's rooms. You may still both participate in a third learner's shared room. Unblocking does not restore removed room permissions.</p>${state.blocks.map(b=>`<div class="connection-row"><strong>${esc(b.handle)}</strong>${btn('Unblock','unblock',b.id)}</div>`).join('')||'<p>No blocked learners.</p>'}</section>`;}
function roomView(){const r=state.room;return `<div class="button-row" style="margin-bottom:22px"><a class="button outline" href="${communityURL()}">← Course community</a></div><div class="room-heading"><h2>${esc(r.title)}</h2><span class="tag">INVITE-ONLY ROOM${r.closed?' · CLOSED':''}</span></div><p class="muted">Hosted by ${esc(r.owner.handle)} · Your editor opens first. Other editors open only when you select a name.</p><div class="study-workbench"><aside id="study-learning"></aside><div id="split-workspace"></div></div><p class="room-privacy-note">Each learner controls their own code. New personal editors are private until shared; the room owner's original editor remains shared with invitees. Saved changes sync every few seconds. Shared code is text-only here: review it as untrusted and use an isolated environment if you run it.</p><div class="room-extras">${chat(true)}<section class="panel"><h2>Room settings</h2>${r.role==='owner'?`<p class="safe-note">Invitations let learners join this room and view the owner’s shared editor. Each learner separately chooses whether to share their personal editor.</p><div id="room-members">${membersHTML(r)}</div><form id="invite-form"><label class="field">Invite an accepted study partner<select id="invite-person"><option value="">Choose a connection</option>${state.connections.filter(c=>c.status==='accepted'&&!r.members.some(m=>m.id===c.learner.id)).map(c=>`<option value="${c.learner.id}">${esc(c.learner.handle)}</option>`).join('')}</select></label><button class="button outline">Invite to room</button></form><div class="button-row">${btn(r.closed?'Reopen room':'Close room',r.closed?'reopenRoom':'closeRoom',r.id)}</div>`:`<p class="muted">The room owner manages invitations. Ask an editor's owner to grant access before changing their work.</p><h3>Room members</h3><p class="muted">${esc(r.owner.handle)} · room owner</p>${r.members.map(m=>`<p class="muted">${esc(m.handle)}</p>`).join('')}`}</section></div>`;}
function membersHTML(r){return r.members.map(m=>`<div class="room-access"><div><strong>${esc(m.handle)}</strong><small>${esc(m.role)} access</small></div><select data-member="${m.id}" aria-label="Access for ${esc(m.handle)}"><option value="viewer" ${m.role==='viewer'?'selected':''}>View owner’s code</option><option value="editor" ${m.role==='editor'?'selected':''}>Edit owner’s code</option><option value="remove">Remove access</option></select></div>`).join('')||'<p class="muted">No invited learners. This code is still private to you.</p>';}
async function refresh(){const next=await api();const preserved={};const groups={code:['shared-code'],comment:['comment-body'],create:['room-title','room-language','room-code'],preferences:['community-handle','discoverable']};for(const group of dirty)for(const id of groups[group]||[]){const e=$(id);if(e)preserved[id]={value:e.value,checked:e.checked};}const oldRevision=revision;state=next;render();for(const [id,v]of Object.entries(preserved)){const e=$(id);if(e){e.value=v.value;if(e.type==='checkbox')e.checked=v.checked;}}if(dirty.has('code')&&state.room){revision=oldRevision;$('room-revision').textContent='Revision '+revision;if(state.room.revision!==revision)$('remote-update').hidden=false;}}function render(){document.title='CodeTrail — '+courseName()+' community';$('breadcrumb').textContent='STUDY TOGETHER';document.querySelectorAll('.sidebar nav a').forEach(a=>{if(a.getAttribute('href')==='/community'){a.classList.add('active');a.setAttribute('aria-current','page');}});$('hub-account').textContent='Sign out ↗';$('hub-account').href='/signout-with-chatgpt?return_to=%2F';let main=base();if(!state.enrolled)main+=joinForm();else if(roomId)main+=roomView();else main+=`<div class="community-tabs" role="tablist">${[['learning','Learn & practice'],['discussion','Discussion'],['learners','Learners'],['connections','Connections'],['rooms','Coding rooms'],['settings','Preferences']].map(([id,label])=>`<button data-tab="${id}" role="tab" aria-selected="false">${label}</button>`).join('')}</div><section class="community-section" id="section-learning"><div id="study-learning"></div></section><section class="community-section" id="section-discussion" hidden>${chat()}</section><section class="community-section" id="section-learners" hidden>${people()}</section><section class="community-section" id="section-connections" hidden>${connections()}</section><section class="community-section" id="section-rooms" hidden>${rooms()}</section><section class="community-section" id="section-settings" hidden>${settings()}</section>`;$('hub-content').innerHTML=main;$('community-course').onchange=e=>location.assign(communityURL(e.target.value));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));if(!roomId&&state.enrolled)selectTab(location.hash.slice(1)||'learning');bind();if(roomId&&state.enrolled)window.CodeTrailSplit?.mount({state,self,courseId,roomId,notify});if(state.enrolled)window.CodeTrailLearning?.mount({courseId,roomId,self,isHost:state.room?.role==='owner',focus:state.room?.focus,setFocus:(lessonId,problemIndex)=>api({action:'setFocus',roomId,lessonId,problemIndex})});}
function selectTab(t){if(!['learning','discussion','learners','connections','rooms','settings'].includes(t))t='learning';document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===t);b.setAttribute('aria-selected',String(b.dataset.tab===t));});document.querySelectorAll('.community-section').forEach(s=>s.hidden=s.id!=='section-'+t);history.replaceState(null,'',communityURL()+'#'+t);}
function bind(){if($('join-form')){$('join-form').oninput=()=>dirty.add('preferences');$('join-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api({action:'join',handle:$('community-handle').value,discoverable:$('discoverable').checked});dirty.delete('preferences');await refresh();notify('Your course enrollment and discovery preference are saved.');}catch(err){notify(err.message);b.disabled=false;}};}if($('chat-form')){$('comment-body').oninput=()=>dirty.add('comment');$('chat-form').onsubmit=async e=>{e.preventDefault();const b=$('post-comment');b.disabled=true;$('comment-body').readOnly=true;try{await api({action:'message',roomId,body:$('comment-body').value});$('comment-body').value='';dirty.delete('comment');await poll();}catch(err){notify(err.message);}finally{b.disabled=!!state.room?.closed;$('comment-body').readOnly=false;}};}if($('room-form')){$('room-form').oninput=()=>dirty.add('create');$('room-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button:not([type="button"])');b.disabled=true;try{const r=await api({action:'createRoom',title:$('room-title').value,language:$('room-language').value,code:$('room-code').value});dirty.delete('create');location.assign(communityURL(courseId,r.roomId));}catch(err){notify(err.message);b.disabled=false;}};$('load-drafts').onclick=async()=>{try{const [old,academy]=await Promise.all(['/api/progress','/api/academy'].map(async u=>{const r=await fetch(u,{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('Could not read saved drafts. Sign in again or retry.');return r.json();}));if(old.account!==academy.account)throw Error('Your account changed while loading drafts. Reload before sharing.');const identityBytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('codetrail-community-v1|'+old.account));const identity=[...new Uint8Array(identityBytes)].map(x=>x.toString(16).padStart(2,'0')).join('');if(identity!==self)throw Error('Your account changed. Reload before loading private drafts.');sharedDrafts=[...Object.entries(old.state.drafts||{}).map(([key,code])=>({label:'Programming · '+key,code,language:key.includes('java')?'java':'python'})),...Object.entries(academy.state.codeDrafts||{}).map(([key,code])=>({label:'AI academy · '+key,code,language:'python'}))];$('saved-drafts').hidden=false;$('saved-drafts').innerHTML='<option value="">Select a draft to copy</option>'+sharedDrafts.map((d,i)=>`<option value="${i}">${esc(d.label)}</option>`).join('');if(!sharedDrafts.length)notify('No saved drafts yet. You can paste code directly.');}catch(err){notify(err.message);}};$('saved-drafts').onchange=e=>{if(e.target.value==='')return;const d=sharedDrafts[Number(e.target.value)];if(!d)return;if($('room-code').value&&!confirm('Replace the code in this new-room form with the selected draft?'))return;$('room-code').value=d.code;$('room-language').value=d.language;dirty.add('create');};}
if($('shared-code')){$('shared-code').oninput=()=>{dirty.add('code');$('room-status').textContent='Unsaved shared-code edits. Other learners still see the last saved version.';};$('shared-code').onkeydown=e=>{if(e.key==='Tab'&&!e.target.readOnly){e.preventDefault();e.target.setRangeText('    ',e.target.selectionStart,e.target.selectionEnd,'end');dirty.add('code');}};$('save-shared').onclick=async()=>{const b=$('save-shared'),sent=$('shared-code').value;b.disabled=true;try{const r=await api({action:'saveCode',roomId,revision,code:sent});revision=r.revision;state.room.revision=revision;state.room.code=sent;$('room-revision').textContent='Revision '+revision;if($('shared-code').value===sent)dirty.delete('code');$('room-status').textContent=dirty.has('code')?'Earlier version shared; newer edits are unsaved.':'Code shared with invited learners.';$('remote-update').hidden=true;}catch(err){$('room-status').textContent=err.message;}finally{b.disabled=state.room.role==='viewer'||state.room.closed;}};$('reload-shared').onclick=async()=>{if(dirty.has('code')&&!confirm('Replace your unsaved editor text with the latest shared version? Copy your text first if you want to keep it.'))return;try{const r=await api(null,true);state.room=r.room;revision=r.room.revision;$('shared-code').value=r.room.code;dirty.delete('code');$('room-revision').textContent='Revision '+revision;$('remote-update').hidden=true;$('room-status').textContent='Latest shared code loaded.';}catch(err){notify(err.message);}};$('copy-shared').onclick=async()=>{try{await navigator.clipboard.writeText($('shared-code').value);$('room-status').textContent='Copied your editor text. Treat any peer code as untrusted before running it.';}catch{$('shared-code').focus();$('shared-code').select();$('room-status').textContent='Copy the selected code with your keyboard or device menu.';}};}
if($('invite-form'))$('invite-form').onsubmit=async e=>{e.preventDefault();if(!$('invite-person').value)return;const b=e.target.querySelector('button');b.disabled=true;try{await api({action:'invite',roomId,learnerId:$('invite-person').value});await refresh();notify('Partner invited with read-only access.');}catch(err){notify(err.message);b.disabled=false;}};document.querySelectorAll('[data-member]').forEach(el=>el.onchange=async()=>{const previous=state.room.members.find(m=>m.id===el.dataset.member)?.role||'viewer';const role=el.value;if(role==='editor'&&!confirm('Allow this learner to modify the shared code in this room?')){el.value=previous;return;}el.disabled=true;try{await api({action:'role',roomId,learnerId:el.dataset.member,role});await refresh();notify('Room access updated.');}catch(err){notify(err.message);el.value=previous;el.disabled=false;}});}
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;let body={action:a};if(a==='connect')body.learnerId=id;if(a==='accept'||a==='decline')body={action:'connectionReply',connectionId:id,status:a==='accept'?'accepted':'declined'};if(a==='block'){if(!confirm('Block this learner? Their comments will be hidden and access to each other’s rooms removed. You may still both be in another learner’s shared room.'))return;body.learnerId=id;}if(a==='unblock')body.learnerId=id;if(a==='leave'&&!confirm('Leave this course community? Your rooms will close, and connections and invited-room access here will be removed. Existing comments remain.'))return;if(a==='closeRoom'||a==='reopenRoom')body={action:'closeRoom',roomId:id,closed:a==='closeRoom'};if(a==='deleteMessage'||a==='restoreMessage')body.messageId=id;if(a==='report'){const reason=prompt('Why are you reporting this comment? It will be hidden for you and the report recorded. Immediate human review is not guaranteed.');if(!reason)return;body={action:'report',messageId:id,reason};}b.disabled=true;try{await api(body);await refresh();notify(a==='report'?'Comment hidden for you; your report was recorded. Immediate moderation is not guaranteed.':'Updated.');}catch(err){notify(err.message);b.disabled=false;}});
async function poll(){if(polling||document.hidden||!state?.enrolled)return;polling=true;try{const r=await api(null,!!roomId);if(!r.enrolled){if(roomId||dirty.size){state.enrolled=false;window.CodeTrailSplit?.lock('You are no longer enrolled.');document.querySelectorAll('#hub-content textarea,#hub-content input').forEach(e=>e.readOnly=true);document.querySelectorAll('#hub-content button').forEach(b=>{if(b.id!=='copy-shared'&&b.dataset.command!=='copy')b.disabled=true;});notify('You are no longer enrolled. Unsaved text has been kept for copying; reload to join again.');return;}state=r;render();return;}if(roomId){state.room=r.room;window.CodeTrailSplit?.update({...state,room:r.room});window.CodeTrailLearning?.updateFocus(r.room.focus);}state.messages=r.messages;if($('chat-feed')){const f=$('chat-feed'),atEnd=f.scrollHeight-f.scrollTop-f.clientHeight<60;const html=messagesHTML(r.messages);if(f.innerHTML!==html){f.innerHTML=html;if(atEnd)f.scrollTop=f.scrollHeight;}}if($('poll-status'))$('poll-status').textContent='Updated '+new Date().toLocaleTimeString();}catch(err){if($('poll-status'))$('poll-status').textContent=err.message;if(roomId&&[401,403,404].includes(err.status)){window.CodeTrailSplit?.lock('Room access or your session changed.');if($('shared-code'))$('shared-code').readOnly=true;if($('save-shared'))$('save-shared').disabled=true;if($('post-comment'))$('post-comment').disabled=true;notify('Room access or your session changed. Your current text has been kept; copy unsaved work before leaving.');}}finally{polling=false;}}
async function start(){try{const r=await fetch('/academy-courses.json',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('Please sign in to access learning communities.');courses=[{id:'python-dsa',title:'Python & Data Structures'},{id:'java-basics',title:'Java Basics'},...(await r.json()).map(c=>({id:c.id,title:c.title}))];if(!courses.some(c=>c.id===courseId))courseId='python-dsa';state=await api();render();setInterval(poll,roomId?4000:10000);}catch(err){$('hub-content').innerHTML='<div class="notice error">'+esc(err.message)+' <a href="/signin-with-chatgpt?return_to='+encodeURIComponent(location.pathname+location.search)+'">Sign in or retry ↗</a></div>';}}addEventListener('beforeunload',e=>{if(dirty.size){e.preventDefault();e.returnValue='';}});start();
})();
